<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { request } from '../../services/request.js'

const loading = ref(true), saving = ref(false), error = ref(''), errorCode = ref(''), tab = ref('models'), showForm = ref(false)
const models = ref([]), usage = ref({ logs: [], budget: null })
const budget = reactive({ limitAmount: '', currency: 'CNY' })
const tts = reactive({ provider: 'aliyun_nls', endpoint: 'https://nls-gateway-cn-shanghai.aliyuncs.com/stream/v1/tts', voice: 'aixia', sampleRate: 16000, appKey: '', accessKeyId: '', accessKeySecret: '', logs: [] })
const emptyForm = () => ({ id: '', providerCode: 'deepseek', modelCode: '', displayName: '', specification: 'flash', baseUrl: 'https://api.deepseek.com/chat/completions', apiKeyParamKey: 'AI_DEEPSEEK_API_KEY', apiKey: '', enabled: false, defaultModel: false, maxOutputTokens: 1200, timeoutSeconds: 60, currency: 'CNY', inputPerMillion: 0, outputPerMillion: 0, expectedVersion: null })
const form = reactive(emptyForm())
const budgetRate = computed(() => { const row = usage.value.budget; if (!row || !Number(row.limit_amount)) return 0; return Math.min(100, Math.round((Number(row.spent_amount || 0) + Number(row.reserved_amount || 0)) * 100 / Number(row.limit_amount))) })

async function load() {
  loading.value = true; error.value = ''; errorCode.value = ''
  try {
    const [modelRows, usageData, ttsData] = await Promise.all([request('/admin/ai/models'), request('/admin/ai/usage'), request('/admin/ai/tts')])
    models.value = modelRows; usage.value = usageData; Object.assign(tts, ttsData, { appKey: '', accessKeyId: '', accessKeySecret: '' })
    if (usageData.budget) { budget.limitAmount = usageData.budget.limit_amount; budget.currency = usageData.budget.currency }
  } catch (e) { error.value = e.message; errorCode.value = e.code || '' } finally { loading.value = false }
}
function createModel() { Object.assign(form, emptyForm()); showForm.value = true }
function editModel(model) { Object.assign(form, emptyForm(), model, { id: model.id, apiKey: '', expectedVersion: model.versionNo }); showForm.value = true }
async function saveModel() {
  saving.value = true; error.value = ''; errorCode.value = ''
  try { const path = form.id ? `/admin/ai/models/${form.id}` : '/admin/ai/models'; await request(path, { method: form.id ? 'PUT' : 'POST', body: JSON.stringify(form) }); showForm.value = false; await load() }
  catch (e) { error.value = e.message; errorCode.value = e.code || '' } finally { saving.value = false }
}
async function saveBudget() { saving.value = true; try { usage.value = await request('/admin/ai/budget', { method: 'PUT', body: JSON.stringify(budget) }) } catch (e) { error.value = e.message } finally { saving.value = false } }
async function reconcile(row) { const raw = window.prompt('请输入供应商账单核定费用（未收费输入 0）', '0'); if (raw === null) return; try { usage.value = await request(`/admin/ai/attempts/${value(row,'id')}/reconcile`, { method: 'PUT', body: JSON.stringify({ settledAmount: raw }) }) } catch (e) { error.value = e.message } }
async function saveTts() { saving.value = true; error.value = ''; errorCode.value = ''; try { const data = await request('/admin/ai/tts', { method: 'PUT', body: JSON.stringify(tts) }); Object.assign(tts, data, { appKey: '', accessKeyId: '', accessKeySecret: '' }) } catch (e) { error.value = e.message; errorCode.value = e.code || '' } finally { saving.value = false } }
function value(row, key) { return row[key] ?? row[key.toUpperCase()] ?? '-' }
function time(value) { if (!value) return '-'; return new Intl.DateTimeFormat('zh-CN', { timeZone: 'Asia/Shanghai', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(value)) }
onMounted(load)
</script>

<template>
  <section>
    <div class="page-heading"><div><h1>AI 模型与费用</h1><p>管理可用模型、规格、冻结价格与调用账本；不展示用户问题和回答正文。</p></div><button class="primary-button add" @click="createModel">+ 添加模型</button></div>
    <div v-if="error" class="notice error"><strong>{{ error }}</strong><small v-if="errorCode==='CREDENTIAL_ENCRYPTION_NOT_CONFIGURED'">启动后端前设置环境变量，例如 <code>export AI_CREDENTIAL_ENCRYPTION_KEY='请替换为至少-32-位-随机字符串'</code>，然后重启后端并重新保存本页密钥。不要使用示例值。</small></div>
    <div class="tabs"><button :class="{active:tab==='models'}" @click="tab='models'">模型配置</button><button :class="{active:tab==='usage'}" @click="tab='usage'">日志与费用</button><button :class="{active:tab==='tts'}" @click="tab='tts'">语音合成</button></div>
    <div v-if="loading" class="panel state">正在读取 AI 配置…</div>
    <template v-else-if="tab==='models'">
      <div class="model-grid">
        <article v-for="model in models" :key="model.id" class="panel model-card">
          <div class="model-top"><div><span class="spec">{{ model.specification }}</span><span v-if="model.defaultModel" class="default">默认</span><h3>{{ model.displayName }}</h3><code>{{ model.providerCode }} / {{ model.modelCode }}</code></div><span :class="['state-pill', model.enabled ? 'on' : 'off']">{{ model.enabled ? '已启用' : '已停用' }}</span></div>
          <dl><div><dt>凭据</dt><dd>{{ model.credentialConfigured ? '已配置' : '未配置' }}</dd></div><div><dt>输入价</dt><dd>{{ model.inputPerMillion }} {{ model.currency }} / 百万 token</dd></div><div><dt>输出价</dt><dd>{{ model.outputPerMillion }} {{ model.currency }} / 百万 token</dd></div></dl>
          <div v-if="Number(model.inputPerMillion)===0 && Number(model.outputPerMillion)===0" class="price-warning">价格尚未核实，小程序会阻止调用。</div>
          <button class="edit" @click="editModel(model)">编辑配置</button>
        </article>
      </div>
    </template>
    <template v-else-if="tab==='usage'">
      <div class="panel budget-card"><div><h3>本月费用预算</h3><p>已用 {{ usage.budget?.spent_amount || 0 }} + 预留 {{ usage.budget?.reserved_amount || 0 }} {{ usage.budget?.currency || budget.currency }}</p><div class="budget-track"><i :style="{width:budgetRate+'%'}"></i></div></div><form @submit.prevent="saveBudget"><input v-model="budget.limitAmount" type="number" min="0.000001" step="0.000001" placeholder="本月上限"/><select v-model="budget.currency"><option>CNY</option><option>USD</option></select><button class="primary-button" :disabled="saving">保存预算</button></form></div>
      <div class="panel log-panel"><table><thead><tr><th>时间</th><th>模型 / 规格</th><th>状态</th><th>Token</th><th>结算费用</th><th>请求 ID</th><th>错误 / 操作</th></tr></thead><tbody><tr v-for="row in usage.logs" :key="value(row,'id')"><td>{{ time(value(row,'started_at')) }}</td><td>{{ value(row,'display_name') }}<small>{{ value(row,'specification') }}</small></td><td>{{ value(row,'state') }}</td><td>{{ value(row,'input_tokens') }} / {{ value(row,'output_tokens') }}</td><td>{{ value(row,'settled_amount') }} {{ value(row,'currency') }}</td><td><code>{{ value(row,'provider_request_id') }}</code></td><td>{{ value(row,'error_code') }} <button v-if="value(row,'state')==='unknown'" class="reconcile" @click="reconcile(row)">核对费用</button></td></tr><tr v-if="!usage.logs.length"><td colspan="7" class="empty">暂无 AI 调用记录</td></tr></tbody></table></div>
    </template>
    <template v-else>
      <form class="panel tts-card" @submit.prevent="saveTts"><div class="tts-heading"><div><h3>阿里云语音合成</h3><p>AppKey 与 AccessKey 仅加密保存在服务端，不下发到小程序。</p></div><span :class="['state-pill',tts.ready?'on':'off']">{{ tts.ready ? '凭据已配置' : '待配置' }}</span></div><div class="form-grid"><label class="wide">接口地址<input v-model.trim="tts.endpoint" type="url" required/></label><label>英语音色<input v-model.trim="tts.voice" required placeholder="例如 aixia"/></label><label>采样率<select v-model.number="tts.sampleRate"><option :value="8000">8000 Hz</option><option :value="16000">16000 Hz</option></select></label><label>项目 AppKey<input v-model="tts.appKey" type="password" :placeholder="tts.appKeyConfigured?'已配置；留空不修改':'请输入 AppKey'"/></label><label>AccessKey ID<input v-model="tts.accessKeyId" type="password" :placeholder="tts.accessKeyIdConfigured?'已配置；留空不修改':'请输入 AccessKey ID'"/></label><label>AccessKey Secret<input v-model="tts.accessKeySecret" type="password" :placeholder="tts.accessKeySecretConfigured?'已配置；留空不修改':'请输入 AccessKey Secret'"/></label></div><div class="tts-actions"><span>此状态只表示凭据已保存；实际鉴权、NLS 权限与 OSS 写入结果以下方调用日志为准。</span><button class="primary-button" :disabled="saving">{{saving?'保存中…':'保存 TTS 配置'}}</button></div></form>
      <div class="panel log-panel"><table><thead><tr><th>时间</th><th>目标</th><th>音色</th><th>字符数</th><th>状态</th><th>请求 ID</th><th>错误</th></tr></thead><tbody><tr v-for="row in tts.logs" :key="value(row,'id')"><td>{{time(value(row,'created_at'))}}</td><td>{{value(row,'target_type')}}</td><td>{{value(row,'voice')}}</td><td>{{value(row,'char_count')}}</td><td>{{value(row,'state')}}</td><td><code>{{value(row,'provider_request_id')}}</code></td><td>{{value(row,'error_code')}}</td></tr><tr v-if="!tts.logs?.length"><td colspan="7" class="empty">暂无语音合成记录</td></tr></tbody></table></div>
    </template>
  </section>

  <div v-if="showForm" class="modal-mask"><form class="model-modal" @submit.prevent="saveModel"><div class="modal-head"><div><h2>{{ form.id ? '编辑模型' : '添加模型' }}</h2><p>API Key 只用于写入加密配置，保存后不回显。</p></div><button type="button" @click="showForm=false">×</button></div><div class="form-grid"><label>供应商<input v-model.trim="form.providerCode" required/></label><label>模型代码<input v-model.trim="form.modelCode" required/></label><label>显示名称<input v-model.trim="form.displayName" required/></label><label>规格<select v-model="form.specification"><option value="flash">Flash</option><option value="pro">Pro</option><option value="custom">自定义</option></select></label><label class="wide">API 地址<input v-model.trim="form.baseUrl" type="url" required/></label><label>密钥参数名<input v-model.trim="form.apiKeyParamKey" required/></label><label>API Key<input v-model="form.apiKey" type="password" :placeholder="form.credentialConfigured ? '已配置；留空不修改' : '输入后加密保存'"/></label><label>输入价 / 百万 token<input v-model.number="form.inputPerMillion" type="number" min="0" step="0.000001" required/></label><label>输出价 / 百万 token<input v-model.number="form.outputPerMillion" type="number" min="0" step="0.000001" required/></label><label>货币<select v-model="form.currency"><option>CNY</option><option>USD</option></select></label><label>最大输出 token<input v-model.number="form.maxOutputTokens" type="number" min="1" max="8192"/></label><label>超时秒数<input v-model.number="form.timeoutSeconds" type="number" min="5" max="120"/></label></div><div class="checks"><label><input v-model="form.enabled" type="checkbox"/> 启用</label><label><input v-model="form.defaultModel" type="checkbox"/> 设为默认模型</label></div><div class="modal-actions"><button type="button" @click="showForm=false">取消</button><button class="primary-button" :disabled="saving">{{ saving ? '保存中…' : '保存模型' }}</button></div></form></div>
</template>

<style scoped>
.add{padding:0 20px}.tabs{display:flex;gap:24px;margin:28px 0 18px;border-bottom:1px solid #dde5f0}.tabs button{padding:0 4px 12px;border:0;border-bottom:3px solid transparent;background:transparent;color:#6f7d96}.tabs button.active{border-color:#126ff6;color:#126ff6;font-weight:700}.state{padding:70px;text-align:center;color:#71809b}.notice{margin-top:18px;padding:12px 15px;border-radius:9px}.notice.error{color:#a33b42;background:#fff0f1}.notice strong,.notice small{display:block}.notice small{margin-top:8px;line-height:1.6}.notice code{padding:2px 5px;border-radius:4px;background:#ffe2e4}.model-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.model-card{padding:22px}.model-top{display:flex;justify-content:space-between}.model-card h3{margin:10px 0 4px}.model-card code{color:#7b879d}.spec,.default,.state-pill{display:inline-block;padding:4px 8px;border-radius:6px;font-size:11px;text-transform:uppercase}.spec{color:#4161d9;background:#edf0ff}.default{margin-left:7px;color:#08785a;background:#e8f8f2}.state-pill.on{color:#08785a;background:#e8f8f2}.state-pill.off{color:#7b879d;background:#eef1f5}.model-card dl{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:22px 0}.model-card dl div{padding:12px;border-radius:9px;background:#f7f9fd}.model-card dt{color:#7d899f;font-size:11px}.model-card dd{margin:5px 0 0;font-size:13px}.price-warning{padding:10px;border-radius:8px;color:#94631d;background:#fff7e9;font-size:12px}.edit{width:100%;height:38px;margin-top:16px;border:1px solid #cfd9e8;border-radius:8px;color:#176ff1;background:#fff}.budget-card{display:flex;align-items:center;justify-content:space-between;padding:22px}.budget-card h3{margin:0}.budget-card p{margin:7px 0;color:#73809a;font-size:13px}.budget-track{width:380px;height:7px;border-radius:5px;background:#e8edf5;overflow:hidden}.budget-track i{display:block;height:100%;background:#1678f8}.budget-card form{display:flex;gap:8px}.budget-card input,.budget-card select{height:40px;border:1px solid #d7dfeb;border-radius:8px;padding:0 10px}.budget-card button{padding:0 15px}.log-panel{margin-top:18px;overflow:hidden}table{width:100%;border-collapse:collapse}th,td{padding:14px 16px;border-bottom:1px solid #edf1f6;text-align:left;font-size:12px}th{color:#6d7890;background:#f8faff}td small{display:block;margin-top:4px;color:#8893a7;text-transform:uppercase}td code{display:block;max-width:170px;overflow:hidden;text-overflow:ellipsis}.reconcile{display:block;margin-top:6px;border:0;color:#1674f8;background:transparent;font-size:12px}.empty{text-align:center;color:#7c879b}.model-modal{width:760px;max-height:90vh;overflow:auto;padding:28px;border-radius:16px;background:#fff}.modal-head{display:flex;justify-content:space-between}.modal-head h2{margin:0}.modal-head p{margin:6px 0;color:#7a869c;font-size:13px}.modal-head>button{border:0;background:transparent;font-size:28px}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin-top:22px}.form-grid label{color:#44516b;font-size:12px}.form-grid .wide{grid-column:1/-1}.form-grid input,.form-grid select{width:100%;height:41px;margin-top:6px;padding:0 11px;border:1px solid #d8e0ec;border-radius:8px;background:#fff}.checks{display:flex;gap:28px;margin-top:20px;font-size:13px}.modal-actions{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}.modal-actions button{height:42px;padding:0 22px;border:1px solid #d5deeb;border-radius:8px;background:#fff}.modal-actions .primary-button{border:0;background:#096af3}.tts-card{padding:24px}.tts-heading,.tts-actions{display:flex;align-items:center;justify-content:space-between}.tts-heading h3{margin:0}.tts-heading p,.tts-actions span{color:#748099;font-size:12px}.tts-actions{margin-top:22px}.tts-actions button{height:42px;padding:0 20px}
</style>
